<form class="row g-2 align-items-end mb-4" method="get"><div class="col-auto"><label class="form-label small mb-0">Desde</label><input type="date" name="desde" class="form-control" value="<?= e($desde) ?>"></div>
  <div class="col-auto"><label class="form-label small mb-0">Hasta</label><input type="date" name="hasta" class="form-control" value="<?= e($hasta) ?>"></div>
  <div class="col-auto"><button class="btn btn-mi">Ver reporte</button></div>
  <div class="col-auto"><a class="btn btn-outline-mi" href="<?= url('admin/reportes/csv?desde=' . urlencode($desde) . '&hasta=' . urlencode($hasta)) ?>"><i class="bi bi-file-earmark-spreadsheet"></i> Descargar Excel (CSV)</a></div></form>
<div class="row g-3 mb-4"><?php foreach ([['Ventas', cop($r['ventas']), 'cash-coin', 'success'], ['Pedidos pagados', (int) $r['pedidos'], 'bag-check', 'primary'], ['Ticket promedio', cop($r['ticket']), 'receipt', 'secondary'], ['Descuentos dados', cop($r['descuentos']), 'percent', 'danger']] as [$t, $v, $i, $c]): ?>
  <div class="col-6 col-lg-3"><div class="card p-3 stat"><div class="text-<?= $c ?> fs-3"><i class="bi bi-<?= $i ?>"></i></div><div class="small text-muted"><?= $t ?></div><div class="fs-4 fw-bold"><?= $v ?></div></div></div><?php endforeach; ?></div>
<p class="small text-muted">Se cuentan solo pedidos pagados (no incluye pendientes de pago ni cancelados). Pedidos cancelados en el periodo: <b><?= (int) $r['canceladas'] ?></b>.</p>
<div class="row g-3"><div class="col-lg-7"><div class="card p-3"><h6>Ventas por día</h6><div class="table-responsive"><table class="table table-sm align-middle mb-0"><thead><tr><th>Día</th><th>Pedidos</th><th>Ventas</th><th style="width:40%"></th></tr></thead><tbody>
<?php $max = max(array_map(fn($x) => (float) $x['ventas'], $r['por_dia'] ?: [['ventas' => 1]])) ?: 1; foreach ($r['por_dia'] as $d): ?><tr><td><?= fecha($d['dia']) ?></td><td><?= (int) $d['pedidos'] ?></td><td><?= cop($d['ventas']) ?></td><td><div class="barra" style="height:10px;border-radius:6px;background:var(--mi-primary);width:<?= max(3, round($d['ventas'] / $max * 100)) ?>%"></div></td></tr><?php endforeach; ?>
<?php if (!$r['por_dia']): ?><tr><td colspan="4" class="text-center text-muted py-3">Sin ventas en este periodo.</td></tr><?php endif; ?></tbody></table></div></div></div>
  <div class="col-lg-5"><div class="card p-3 mb-3"><h6>Productos más vendidos</h6><table class="table table-sm mb-0"><thead><tr><th>Producto</th><th>Unid.</th><th>Ventas</th></tr></thead><tbody>
<?php foreach ($r['top'] as $t): ?><tr><td><?= e($t['producto']) ?></td><td><?= (int) $t['unidades'] ?></td><td><?= cop($t['ventas']) ?></td></tr><?php endforeach; ?><?php if (!$r['top']): ?><tr><td colspan="3" class="text-muted text-center">—</td></tr><?php endif; ?></tbody></table></div>
  <div class="card p-3"><h6>Por modalidad</h6><table class="table table-sm mb-0"><tbody><?php foreach ($r['por_modalidad'] as $m): ?><tr><td><?= $m['modalidad'] === 'domicilio' ? 'Domicilio' : 'Recogida en tienda' ?></td><td><?= (int) $m['pedidos'] ?> pedidos</td><td class="text-end"><?= cop($m['ventas']) ?></td></tr><?php endforeach; ?><?php if (!$r['por_modalidad']): ?><tr><td class="text-muted text-center">—</td></tr><?php endif; ?></tbody></table></div></div></div>
